tool.command:
@PREPARE_INPUT_FILE@ #set $section = $sec_restrict @PREPARE_TARGETS_FILE@ @PREPARE_REGIONS_FILE@ #set $section = $sec_default #set $genotypes_vcf = None #if $section.genotypes: #if $section.genotypes.is_of_type('vcf') #set $genotypes_vcf = 'genotypes.vcf.gz' bgzip -c '$section.genotypes' > $genotypes_vcf && bcftools index $genotypes_vcf && #elif $section.genotypes.is_of_type('bcf') #set $genotypes_vcf = 'genotypes.bcf' ln -s '$section.genotypes' $genotypes_vcf && #if $section.genotypes.metadata.bcf_index: ln -s $section.genotypes.metadata.bcf_index ${genotypes_vcf}.csi && #else bcftools index $genotypes_vcf && #end if #end if #end if
bcftools @EXECUTABLE@
## Default section #set $section = $sec_default
#if $genotypes_vcf: --genotypes $genotypes_vcf #end if
#if $section.genotypes: --genotypes '${section.genotypes}' #end if
#if str($section.distinctive_sites) != '': --distinctive-sites '${section.distinctive_sites}' #end if
${section.dry_run}
#if str($section.error_probability) != '': --error-probability ${section.error_probability} #end if
${section.homs_only}
${section.keep_refs}
#if str($section.n_matches) != '': --n-matches ${section.n_matches} #end if
${section.no_HWE_prob}
#if str($section.pairs) != '': --pairs '${section.pairs}' #end if
#if $section.pairs_file: --pairs-file '${section.pairs_file}' #end if
#if str($section.use) != '': --use '${section.use}' #end if
@VERBOSITY@
#set $section = $sec_restrict @SAMPLES@ @INCLUDE@ @EXCLUDE@ @REGIONS@ @TARGETS@
## Primary Input/Outputs
@INPUT_FILE@ > '$output_file'

tool.help:
=====================================
 bcftools @EXECUTABLE@
=====================================

Check sample identity. With no -g BCF given, multi-sample cross-check is performed.

@REGIONS_HELP@
@TARGETS_HELP@

@BCFTOOLS_MANPAGE@#@EXECUTABLE@

@BCFTOOLS_HOWTOS@
